mapper.delete:
DELETE FROM ops_instances
WHERE (last_heartbeat_at IS NULL OR last_heartbeat_at < #{before})
 AND instance_id <> #{exclude}

mapper.select:
SELECT metric_key AS metricKey, sample_time AS sampleTime, AVG(metric_value) AS metricValue, MAX(metric_value) AS maxValue, MIN(metric_value) AS minValue FROM ops_metric_snapshots WHERE sample_time BETWEEN #{from} AND #{to}
AND metric_key IN #{k}
GROUP BY metric_key, sample_time ORDER BY sample_time ASC

mapper.update:
UPDATE ops_alarm_rules
name = #{name}, metric_key = #{metricKey}, operator = #{operator}, threshold = #{threshold}, duration_checks = #{durationChecks}, level = #{level}, enabled = #{enabled}, silence_minutes = #{silenceMinutes}, channels = #{channels}, description = #{description},
WHERE id = #{id}

mapper.select:
SELECT  FROM ops_alarm_records

    AND status = #{status}
    AND level = #{level}

        AND (rule_name LIKE CONCAT('%', #{keyword}, '%') OR metric_key LIKE CONCAT('%', #{keyword}, '%')
             OR IFNULL(message, '') LIKE CONCAT('%', #{keyword}, '%'))

    AND fired_at >= #{from}
    AND fired_at <= #{to}

ORDER BY fired_at DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(1) FROM ops_alarm_records

    AND status = #{status}
    AND level = #{level}

        AND (rule_name LIKE CONCAT('%', #{keyword}, '%') OR metric_key LIKE CONCAT('%', #{keyword}, '%')
             OR IFNULL(message, '') LIKE CONCAT('%', #{keyword}, '%'))

    AND fired_at >= #{from}
    AND fired_at <= #{to}

mapper.update:
UPDATE ops_alarm_records
SET status = 'RESOLVED', resolved_at = #{resolvedAt},
    duration_seconds = #{durationSeconds}, metric_value = #{value}
WHERE id = #{id}

UPDATE ops_jobs
job_name = #{jobName}, cron = #{cron}, handler = #{handler}, params = #{params}, enabled = #{enabled},
WHERE id = #{id}

UPDATE ops_job_records
SET status = #{status}, end_at = #{endAt}, duration_ms = #{durationMs}, message = #{message}
WHERE id = #{id}

mapper.select:
SELECT id, job_id, job_code, status, trigger_type, instance_id, start_at, end_at,
       duration_ms, message, created_at
FROM ops_job_records

    AND job_id = #{jobId}
    AND status = #{status}

ORDER BY start_at DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(1) FROM ops_job_records

    AND job_id = #{jobId}
    AND status = #{status}

SELECT status, COUNT(1) AS cnt FROM ai_tasks
AND created_at >= #{from}
GROUP BY status

SELECT task_type AS taskType, COUNT(1) AS cnt, SUM(CASE WHEN status = 2 THEN 1 ELSE 0 END) AS success, SUM(CASE WHEN status = 3 THEN 1 ELSE 0 END) AS failed, AVG(CASE WHEN finished_at IS NOT NULL AND started_at IS NOT NULL THEN TIMESTAMPDIFF(SECOND, started_at, finished_at) END) AS avgSeconds FROM ai_tasks
AND created_at >= #{from}
GROUP BY task_type ORDER BY cnt DESC

SELECT COUNT(1) FROM ai_tasks

    AND status = #{status}
    AND created_at >= #{from}

mapper.update:
UPDATE ai_tasks
SET status = 3, error_code = 106002, error_message = 'AI 任务超时（运维扫描置为失败）',
    finished_at = NOW()
WHERE status IN (0, 1)
  AND created_at < #{before}
LIMIT #{limit}

mapper.select:
SELECT status, COUNT(1) AS cnt, IFNULL(SUM(amount_cents), 0) AS amountCents FROM orders
AND created_at >= #{from}
GROUP BY status

SELECT COUNT(1) FROM orders
WHERE status IN (1, 2)
AND paid_at >= #{from}

SELECT DATE_FORMAT(created_at, '%Y-%m-%d') AS day, COUNT(1) AS cnt
FROM users WHERE created_at >= #{from}
GROUP BY day ORDER BY day ASC

SELECT IFNULL(biz_type, 'unknown') AS bizType, COUNT(1) AS cnt, IFNULL(SUM(size_bytes), 0) AS sizeBytes FROM uploads
AND created_at >= #{from}
GROUP BY biz_type ORDER BY cnt DESC

SELECT user_id AS userId, COUNT(1) AS cnt, IFNULL(SUM(size_bytes), 0) AS sizeBytes
FROM uploads WHERE created_at >= #{from}
GROUP BY user_id ORDER BY sizeBytes DESC LIMIT #{limit}

mapper.delete:
DELETE FROM uploads
WHERE created_at < #{before}
  AND IFNULL(related_id, '') = ''

mapper.select:
SELECT l.id, l.admin_user_id AS adminUserId, u.username, l.module, l.action,
       l.target_id AS targetId, l.ip, l.user_agent AS userAgent, l.created_at AS createdAt
FROM admin_logs l
LEFT JOIN admin_users u ON u.id = l.admin_user_id

    AND l.module = #{module}
    AND l.action = #{action}

        AND (IFNULL(u.username, '') LIKE CONCAT('%', #{keyword}, '%')
             OR l.action LIKE CONCAT('%', #{keyword}, '%')
             OR IFNULL(l.target_id, '') LIKE CONCAT('%', #{keyword}, '%')
             OR IFNULL(l.ip, '') LIKE CONCAT('%', #{keyword}, '%'))

    AND l.created_at >= #{from}
    AND l.created_at <= #{to}

ORDER BY l.created_at DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(1) FROM admin_logs l LEFT JOIN admin_users u ON u.id = l.admin_user_id

    AND l.module = #{module}
    AND l.action = #{action}

        AND (IFNULL(u.username, '') LIKE CONCAT('%', #{keyword}, '%')
             OR l.action LIKE CONCAT('%', #{keyword}, '%')
             OR IFNULL(l.target_id, '') LIKE CONCAT('%', #{keyword}, '%')
             OR IFNULL(l.ip, '') LIKE CONCAT('%', #{keyword}, '%'))

    AND l.created_at >= #{from}
    AND l.created_at <= #{to}

SELECT id, user_id AS userId, content_type AS contentType, content_id AS contentId,
       check_type AS checkType, check_result AS checkResult, reason, operator,
       created_at AS createdAt
FROM audit_logs

    AND check_result = #{checkResult}
    AND content_type = #{contentType}

        AND (IFNULL(reason, '') LIKE CONCAT('%', #{keyword}, '%')
             OR IFNULL(content_id, '') LIKE CONCAT('%', #{keyword}, '%')
             OR IFNULL(operator, '') LIKE CONCAT('%', #{keyword}, '%'))

    AND created_at >= #{from}
    AND created_at <= #{to}

ORDER BY created_at DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(1) FROM audit_logs

    AND check_result = #{checkResult}
    AND content_type = #{contentType}

        AND (IFNULL(reason, '') LIKE CONCAT('%', #{keyword}, '%')
             OR IFNULL(content_id, '') LIKE CONCAT('%', #{keyword}, '%')
             OR IFNULL(operator, '') LIKE CONCAT('%', #{keyword}, '%'))

    AND created_at >= #{from}
    AND created_at <= #{to}
